/* The tables of M20 · Behaviour and houses. */

export const houses = defineTable(
  'houses',
  { module: 'M20', scope: 'branch', member: 'read' },
  {
    ...baseColumns,
    branchId: branchIdColumn(),
    /** "Jinnah", "Iqbal" */
    name: text().notNull(),
    nameUr: text(),
    /** a hex colour */
    colour: text().notNull(),
    motto: text(),
    houseMasterStaffId: uuid().references((): AnyPgColumn => staff.id),
    isActive: boolean().notNull().default(true),
  },
  (t) => [
    check('houses_colour_hex', sql`${t.colour} ~ '^#[0-9A-Fa-f]{6}$'`),
    uniqueIndex('houses_branch_name_uq').on(t.branchId, t.name).where(live(t)),
  ],
);

export const behaviourCategories = defineTable(
  'behaviour_categories',
  { module: 'M20', scope: 'org', member: 'read' },
  {
    ...baseColumns,
    /** "Helped a classmate", "Late to class", "Fighting" */
    name: text().notNull(),
    nameUr: text(),
    kind: enumText(behaviourCategoryKinds).notNull(),
    /** for negative categories */
    severity: enumText(behaviourCategorySeverities).notNull().default('low'),
    /** positive for positive, negative for negative */
    defaultPoints: integer().notNull(),
    notifyGuardian: enumText(behaviourCategoryNotifyGuardians).notNull().default('digest'),
    /** high-severity records go to the section head first */
    needsReview: boolean().notNull().default(false),
    isActive: boolean().notNull().default(true),
  },
  (t) => [
    check(
      'behaviour_categories_default_points_sign',
      sql`(${t.kind} = 'positive' and ${t.defaultPoints} >= 0) or (${t.kind} = 'negative' and ${t.defaultPoints} <= 0)`,
    ),
    uniqueIndex('behaviour_categories_name_uq').on(t.orgId, t.name).where(live(t)),
  ],
);

export const behaviourRecords = defineTable(
  'behaviour_records',
  {
    module: 'M20',
    scope: 'branch',
    family: 'studentId',
    familyRule: { read: { status: ['recorded', 'confirmed'], visibility: 'family' } },
  },
  {
    ...baseColumns,
    branchId: branchIdColumn(),
    studentId: uuid()
      .references((): AnyPgColumn => students.id)
      .notNull(),
    categoryId: uuid()
      .references((): AnyPgColumn => behaviourCategories.id)
      .notNull(),
    /** copied from the category */
    kind: enumText(behaviourRecordKinds).notNull(),
    points: integer().notNull(),
    /** not in the future */
    occurredOn: dateStr().notNull(),
    /** the student's section that day */
    sectionId: uuid()
      .references((): AnyPgColumn => sections.id)
      .notNull(),
    reportedByStaffId: uuid()
      .references((): AnyPgColumn => staff.id)
      .notNull(),
    /** what the guardian reads */
    description: text(),
    place: text(),
    visibility: enumText(behaviourRecordVisibilities).notNull().default('family'),
    status: enumText(behaviourRecordStatuses).notNull().default('recorded'),
    voidReason: text(),
    concernId: uuid().references((): AnyPgColumn => behaviourConcerns.id),
  },
  (t) => [
    index('behaviour_records_student_occurred_on_idx').on(t.orgId, t.studentId, t.occurredOn),
    index('behaviour_records_branch_occurred_on_kind_idx').on(
      t.orgId,
      t.branchId,
      t.occurredOn,
      t.kind,
    ),
  ],
);

/** Staff-only notes on a record; never shown to families. */
export const behaviourRecordNotes = defineTable(
  'behaviour_record_notes',
  { module: 'M20', scope: 'branch' },
  {
    ...baseColumns,
    branchId: branchIdColumn(),
    behaviourRecordId: uuid()
      .references((): AnyPgColumn => behaviourRecords.id, {
        name: 'behaviour_record_notes_behaviour_record_id_behaviour_r_1f97aa6e',
      })
      .notNull(),
    body: text().notNull(),
    authorId: uuid()
      .references((): AnyPgColumn => profiles.id)
      .notNull(),
  },
);

/** A case that needs follow-up: repeated or serious conduct. */
export const behaviourConcerns = defineTable(
  'behaviour_concerns',
  { module: 'M20', scope: 'branch' },
  {
    ...baseColumns,
    branchId: branchIdColumn(),
    studentId: uuid()
      .references((): AnyPgColumn => students.id)
      .notNull(),
    title: text().notNull(),
    level: enumText(behaviourConcernLevels).notNull().default('class'),
    ownerStaffId: uuid()
      .references((): AnyPgColumn => staff.id)
      .notNull(),
    openedOn: dateStr().notNull(),
    status: enumText(behaviourConcernStatuses).notNull().default('open'),
    guardianInformed: boolean().notNull().default(false),
    closedOn: dateStr(),
    /** required to close */
    outcome: text(),
  },
  (t) => [
    check(
      'behaviour_concerns_outcome_needed',
      sql`${t.status} <> 'closed' or (${t.outcome} is not null and ${t.closedOn} is not null)`,
    ),
  ],
);

export const concernActions = defineTable(
  'concern_actions',
  {
    module: 'M20',
    scope: 'branch',
    family: 'studentId',
    familyRule: { read: { shareWithFamily: true } },
  },
  {
    ...baseColumns,
    branchId: branchIdColumn(),
    concernId: uuid()
      .references((): AnyPgColumn => behaviourConcerns.id)
      .notNull(),
    studentId: uuid()
      .references((): AnyPgColumn => students.id)
      .notNull(),
    action: enumText(concernActionActions).notNull(),
    actionDate: dateStr().notNull(),
    /** required for `suspension` */
    toDate: dateStr(),
    assignedToStaffId: uuid().references((): AnyPgColumn => staff.id),
    note: text(),
    status: enumText(concernActionStatuses).notNull().default('planned'),
    /** suspension */
    approvalRequestId: uuid().references((): AnyPgColumn => approvalRequests.id),
    shareWithFamily: boolean().notNull().default(true),
  },
  (t) => [
    check('concern_actions_to_date_from', sql`${t.toDate} >= ${t.actionDate}`),
    check(
      'concern_actions_to_date_needed',
      sql`${t.action} <> 'suspension' or ${t.toDate} is not null`,
    ),
  ],
);

export const housePoints = defineTable(
  'house_points',
  { module: 'M20', scope: 'branch', appendOnly: true, staff: 'append' },
  {
    ...appendColumns,
    branchId: branchIdColumn(),
    houseId: uuid()
      .references((): AnyPgColumn => houses.id)
      .notNull(),
    /** empty for points given to a whole house */
    studentId: uuid().references((): AnyPgColumn => students.id),
    /** may be negative */
    points: integer().notNull(),
    reason: text().notNull(),
    source: enumText(housePointSources).notNull(),
    behaviourRecordId: uuid().references((): AnyPgColumn => behaviourRecords.id),
    academicYearId: uuid()
      .references((): AnyPgColumn => academicYears.id)
      .notNull(),
    awardedOn: dateStr().notNull(),
    awardedBy: uuid()
      .references((): AnyPgColumn => profiles.id)
      .notNull(),
  },
  (t) => [index('house_points_house_academic_year_idx').on(t.orgId, t.houseId, t.academicYearId)],
);

